SELECT g.account,a.account_name,a.account_type,SUM(g.debit-g.credit) AS net_movement FROM "tabGL Entry" g JOIN "tabAccount" a ON a.name=g.account WHERE (%(company)s = '' OR g.company = %(company)s) AND (%(from_date)s = '' OR g.posting_date >= %(from_date)s) AND (%(to_date)s = '' OR g.posting_date <= %(to_date)s) AND a.account_type IN ('Cash','Bank') GROUP BY g.account,a.account_name,a.account_type ORDER BY a.account_type,g.account
